import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';

export default function Views() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadSellerReels();
    }, []);

    const loadSellerReels = async () => {
        try {
            const response = await ApiService.getSellerReels();
            if (response.success) {
                setReels(response.data);
            }
        } catch (error) {
            console.error('Error loading seller reels:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleBackClick = () => {
        navigate('/studio/seller/profile');
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reel Views</h4>
                    <button 
                        className="btn btn-primary"
                        onClick={handleBackClick}
                    >
                        Back to Profile
                    </button>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h6 className="text-muted">No reels found</h6>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-centered table-nowrap mb-0">
                                    <thead className="table-light">
                                        <tr>
                                            <th>Title</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>
                                                    <h6 className="mb-0">{reel.title}</h6>
                                                </td>
                                                <td>{reel.views || 0}</td>
                                                <td>{reel.likes || 0}</td>
                                                <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
